201	/** Contact listener. It will receive all the contact callbacks. */
202	class CC_DLL EventListenerPhysicsContact : public EventListenerCustom
203	{
204	public:
205	    /** Create the listener. */
206	    static EventListenerPhysicsContact* create();
207	    
208	    /** Check the listener is available.
209	
210	     * @return True if there's one available callback function at least, false if there's no one.
211	     */
212	    virtual bool checkAvailable() override;
213	    
214	    /** Clone an object from this listener.*/
215	    virtual EventListenerPhysicsContact* clone() override;
216	    
217	protected:
218	    /**
219	     * It will be call when two body have contact.
220	     * if return false, it will not invoke callbacks.
221	     */
222	    virtual bool hitTest(PhysicsShape* shapeA, PhysicsShape* shapeB);
223	    
224	public:
225	    /**
226	     * @brief It will called at two shapes start to contact, and only call it once.
227	     */
228	    std::function<bool(PhysicsContact& contact)> onContactBegin;
229	    /**
230	     * @brief Two shapes are touching during this step. Return false from the callback to make world ignore the collision this step or true to process it normally. Additionally, you may override collision values, restitution, or surface velocity values.
231	     */
232	    std::function<bool(PhysicsContact& contact, PhysicsContactPreSolve& solve)> onContactPreSolve;
233	    /**
234	     * @brief Two shapes are touching and their collision response has been processed. You can retrieve the collision impulse or kinetic energy at this time if you want to use it to calculate sound volumes or damage amounts. See cpArbiter for more info
235	     */
236	    std::function<void(PhysicsContact& contact, const PhysicsContactPostSolve& solve)> onContactPostSolve;
237	    /**
238	     * @brief It will called at two shapes separated, and only call it once.
239	     * onContactBegin and onContactSeparate will called in pairs.
240	     */
241	    std::function<void(PhysicsContact& contact)> onContactSeparate;
242	    
243	protected:
244	    bool init();
245	    void onEvent(EventCustom* event);
246	    
247	protected:
248	    EventListenerPhysicsContact();
249	    virtual ~EventListenerPhysicsContact();
250	    
251	    friend class PhysicsWorld;
252	};
